.darma-loader-darma-b9-battery-charging { --accent: var(--loader-color, #16a34a); --accent-2: var(--loader-secondary-color, #86efac); width: calc(var(--loader-size, 84px) * .95); height: calc(var(--loader-size, 84px) * .5); border: calc(var(--loader-size, 84px) * .04) solid var(--accent); border-radius: calc(var(--loader-size, 84px) * .07); position: relative; box-sizing: border-box; }
.darma-loader-darma-b9-battery-charging::after { content: ''; position: absolute; right: calc(var(--loader-size, 84px) * -.07); top: 30%; width: calc(var(--loader-size, 84px) * .05); height: 40%; border-radius: 0 3px 3px 0; background: var(--accent); }
.darma-loader-darma-b9-battery-charging span { position: absolute; inset: 14%; border-radius: calc(var(--loader-size, 84px) * .03); background: linear-gradient(90deg, var(--accent-2), var(--accent)); transform-origin: left center; animation: darma-loader-darma-b9-battery-charging-charge calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b9-battery-charging span::after { content: ''; position: absolute; left: 50%; top: 50%; width: 30%; height: 60%; transform: translate(-50%, -50%); background: #fff; clip-path: polygon(52% 0, 20% 55%, 48% 55%, 40% 100%, 82% 42%, 52% 42%); opacity: .9; }
@keyframes darma-loader-darma-b9-battery-charging-charge { 0% { transform: scaleX(.05); } 80%, 100% { transform: scaleX(1); } }

